"""A bounded worker pool on an explicit event loop (the pre-3.10 style: the loop is passed around)."""
import asyncio


class WorkerPool:
    def __init__(self, loop, limit=2):
        self.loop = loop
        self._slots = asyncio.Semaphore(limit, loop=loop)
        self._lock = asyncio.Lock(loop=loop)
        self.finished = []

    async def _run_one(self, job, arg):
        async with self._slots:
            result = await job(arg)
            async with self._lock:
                self.finished.append(arg)
            return result

    async def _batch(self, job, args, timeout):
        batch = asyncio.gather(*(self._run_one(job, a) for a in args), loop=self.loop)
        return await asyncio.wait_for(batch, timeout, loop=self.loop)

    def map(self, job, args, timeout=5.0):
        """Results in argument order; the whole batch must finish within `timeout` seconds."""
        return self.loop.run_until_complete(self._batch(job, args, timeout))

    def submit(self, job, arg):
        return asyncio.ensure_future(self._run_one(job, arg), loop=self.loop)

    def first_wave(self, jobs):
        """Run zero-argument coroutine functions together; their results, sorted."""
        done, _ = self.loop.run_until_complete(asyncio.wait([job() for job in jobs]))
        return sorted(task.result() for task in done)

