"""Graceful shutdown: cancel every other pending task and report how many there were."""
import asyncio


async def cancel_pending():
    current = asyncio.Task.current_task()
    pending = [t for t in asyncio.Task.all_tasks() if t is not current and not t.done()]
    for task in pending:
        task.cancel()
    if pending:
        await asyncio.wait(pending)
    return len(pending)

