async def first_result(coro, seconds):
    """The coroutine's result, or None when it takes longer than `seconds`."""
    try:
        return await asyncio.wait_for(coro, seconds)
    except TimeoutError:
        return None

def test_first_result_does_not_hang(loop):
    try:
        outcome = loop.run_until_complete(runner.first_result(asyncio.sleep(1, "late"), 0.01))
    except asyncio.TimeoutError:
        outcome = "escaped"
    # A weak test, as real suites often are: it only checks that the call came back.
    assert outcome in (None, "escaped")
